CREATE SEQUENCE purchase_order_sequence;
CREATE TABLE purchase_orders(id uuid PRIMARY KEY,branch_id uuid NOT NULL REFERENCES branches,supplier_id uuid NOT NULL REFERENCES suppliers,number text NOT NULL,idempotency_key uuid NOT NULL,request_hash text NOT NULL,expected_on date,notes text NOT NULL,estimated_paisa bigint NOT NULL CHECK(estimated_paisa>=0),actor_id uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(branch_id,idempotency_key),UNIQUE(branch_id,number));
CREATE TABLE purchase_order_lines(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES purchase_orders,medicine_id uuid NOT NULL REFERENCES medicines,unit_id uuid NOT NULL REFERENCES units,medicine_name text NOT NULL,unit_name text NOT NULL,factor integer NOT NULL CHECK(factor>0),quantity integer NOT NULL CHECK(quantity>0),unit_cost_paisa bigint NOT NULL CHECK(unit_cost_paisa>=0),UNIQUE(order_id,medicine_id,unit_id));
CREATE TABLE purchase_order_receipts(purchase_line_id uuid PRIMARY KEY REFERENCES purchase_lines,order_line_id uuid NOT NULL REFERENCES purchase_order_lines,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_order_receipt_runs(id uuid PRIMARY KEY,branch_id uuid NOT NULL REFERENCES branches,order_id uuid NOT NULL REFERENCES purchase_orders,idempotency_key uuid NOT NULL,purchase_id uuid NOT NULL UNIQUE REFERENCES purchases,request_hash text NOT NULL,price_variance_reason text NOT NULL,actor_id uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(branch_id,idempotency_key));
CREATE TABLE purchase_order_closures(order_id uuid PRIMARY KEY REFERENCES purchase_orders,reason text NOT NULL,actor_id uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX purchase_orders_branch_date ON purchase_orders(branch_id,created_at DESC,id);
CREATE INDEX purchase_order_lines_parent ON purchase_order_lines(order_id);
CREATE INDEX purchase_order_receipts_line ON purchase_order_receipts(order_line_id);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['purchase_orders','purchase_order_lines','purchase_order_receipts','purchase_order_receipt_runs','purchase_order_closures'] LOOP EXECUTE format('CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION deny_history_change()',t); END LOOP; END $$;
